window.dadosSO = {
  title: "Sistemas Operacionais",
  materiaisUrl: "/profmatheus/materiais/sistemas-operacionais.html",
  aulasPorSemana: "3",
  aulas: [
    { icon: "🖥️", t: "Conceitos básicos e evolução dos SO",
      c: "Pense no SO como um gerente de escritório: ele organiza o hardware (CPU, memória, dispositivos) e fornece serviços para os programas (os funcionários). No início (anos 50), os SOs eram como esteiras de fábrica processando lotes (batch). Nos anos 60, a multiprogramação permitiu executar vários programas de uma vez, como um escritório com várias mesas. O Unix (anos 70) trouxe o time-sharing, vários usuários usando o computador ao mesmo tempo. Hoje, kernels monolíticos ou híbridos combinam virtualização e segurança.",
      a: "Pesquise a história do Unix desde 1969 nos Bell Labs até hoje. Crie uma linha do tempo com ao menos 10 marcos como criação do C, BSD, Linux, GNU, POSIX e System V. Espera-se uma linha do tempo visual com datas e descrições breves.",
      p: "Pesquise as diferenças arquiteturais entre Windows (NT kernel híbrido) e Linux (monolítico com módulos) em kernel, sistema de arquivos (NTFS vs ext4), modelo de drivers e licenciamento (proprietário vs GPL).",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Evolução dos SO</text><rect x="20" y="40" width="260" height="30" rx="5" fill="#4338ca"/><text x="150" y="60" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">1950: Sistemas Batch</text><rect x="20" y="75" width="260" height="30" rx="5" fill="#7c3aed"/><text x="150" y="95" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">1960: Multiprogramação</text><rect x="20" y="110" width="260" height="30" rx="5" fill="#2563eb"/><text x="150" y="130" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">1970: Unix / Time-Sharing</text><rect x="20" y="145" width="260" height="30" rx="5" fill="#059669"/><text x="150" y="165" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">1980+: Interfaces Gráficas</text></svg>' },
    { icon: "⚙️", t: "Estrutura de sistemas computacionais",
      c: "Imagine o computador como uma empresa: a CPU é o CEO que toma decisões, a RAM é a mesa de trabalho (espaço temporário), e os dispositivos de E/S são os funcionários de entrega. A CPU alterna entre modo kernel (acesso total, como o dono da empresa) e modo usuário (acesso restrito, como um estagiário). Interrupções são como telefonemas que avisam a CPU sobre eventos. A MMU traduz endereços lógicos (nomes de salas) para físicos (coordenadas reais).",
      a: "Implemente um programa em C que use write() para escrever no terminal. Execute com strace -c para identificar a transição para modo kernel e as syscalls chamadas. Espera-se identificar syscalls como write, mmap e exit_group no trace.",
      p: "Pesquise a tabela IDT (Interrupt Descriptor Table) no x86-64 — como o Linux a configura no boot, os tipos de gate (interrupt/trap/task) e o fluxo de tratamento de interrupções.",
      req: ["gcc","linux","strace"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Sistema Computacional</text><rect x="30" y="40" width="240" height="35" rx="5" fill="#4338ca"/><text x="150" y="62" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">CPU (Modo Kernel / Usuario)</text><rect x="30" y="85" width="110" height="35" rx="5" fill="#7c3aed"/><text x="85" y="107" text-anchor="middle" fill="#fff" font-size="9">Memória RAM</text><rect x="160" y="85" width="110" height="35" rx="5" fill="#2563eb"/><text x="215" y="107" text-anchor="middle" fill="#fff" font-size="9">Dispositivos E/S</text><rect x="30" y="130" width="240" height="30" rx="5" fill="#1e293b"/><text x="150" y="150" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Barramento PCI Express</text><text x="150" y="182" text-anchor="middle" fill="#4338ca" font-size="9">MMU traduz endereços lógicos para físicos</text></svg>' },
    { icon: "📋", t: "Tipos de SO",
      c: "SOs são como diferentes tipos de organização de trabalho. Sistemas batch são como uma linha de montagem que processa tarefas em lote, sem interrupções (IBM OS/360). Time-sharing é como um salão de cabeleireiro que atende vários clientes alternando rapidamente entre eles. SOs distribuídos fazem vários computadores parecerem um só, como uma equipe que parece uma única pessoa. RTOS (FreeRTOS) são como um semáforo de trânsito: respostas em tempo garantido. SOs embarcados rodam em dispositivos dedicados como roteadores e smart TVs.",
      a: "Identifique 3 dispositivos do seu dia a dia que usam SO embarcado (ex: roteador, smart TV, micro-ondas). Descreva qual tipo de SO cada um utiliza e justifique a escolha. Espera-se uma tabela com dispositivo, SO e tipo.",
      p: "Pesquise o FreeRTOS — suas características principais (tarefas, filas, semáforos, timers), escalonamento preemptivo e aplicações em microcontroladores ARM Cortex-M.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Tipos de SO</text><rect x="15" y="40" width="85" height="40" rx="6" fill="#4338ca"/><text x="57" y="58" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Batch</text><text x="57" y="72" text-anchor="middle" fill="#e2e8f0" font-size="8">Lotes</text><rect x="108" y="40" width="85" height="40" rx="6" fill="#7c3aed"/><text x="150" y="58" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Time-Sharing</text><text x="150" y="72" text-anchor="middle" fill="#e2e8f0" font-size="8">Multi-usuario</text><rect x="200" y="40" width="85" height="40" rx="6" fill="#2563eb"/><text x="242" y="58" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Tempo Real</text><text x="242" y="72" text-anchor="middle" fill="#e2e8f0" font-size="8">RTOS</text><rect x="30" y="100" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="122" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Distribuido / Embarcado</text><rect x="50" y="150" width="200" height="25" rx="5" fill="#059669"/><text x="150" y="167" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">FreeRTOS / Linux Embarcado</text></svg>' },
    { icon: "🔄", t: "Conceito de processo",
      c: "Processo é como uma receita sendo executada na cozinha: você tem os ingredientes (dados), os utensílios (registradores) e o estado atual do preparo. Um processo passa por estados: novo (pegou a receita), pronto (ingredientes separados, aguardando fogão), executando (cozinhando), bloqueado (esperando ingrediente chegar) e terminado (prato pronto). O PCB é a ficha da receita com todas as informações. A troca de contexto é como limpar a mesa e preparar para a próxima receita. O escalonador decide qual receita vai para o fogão.",
      a: "Execute ps aux no Linux e identifique processos com diferentes estados: R (running), S (sleeping), D (uninterruptible), Z (zombie). Explique o significado de cada estado. Espera-se capturar a saída e classificar pelos códigos de estado.",
      p: "Pesquise os processos idle (PID 0, executa quando não há nada a fazer) e init (PID 1, primeiro processo de usuário) no Linux — qual a função de cada um na inicialização e operação do sistema.",
      req: ["linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Ciclo de Vida do Processo</text><rect x="100" y="30" width="100" height="30" rx="5" fill="#f59e0b"/><text x="150" y="50" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Novo</text><rect x="100" y="70" width="100" height="30" rx="5" fill="#4338ca"/><text x="150" y="90" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Pronto</text><rect x="200" y="110" width="80" height="30" rx="5" fill="#059669"/><text x="240" y="130" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Executando</text><rect x="20" y="110" width="80" height="30" rx="5" fill="#dc2626"/><text x="60" y="130" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Bloqueado</text><rect x="100" y="155" width="100" height="25" rx="5" fill="#1e293b"/><text x="150" y="173" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Terminado</text></svg>' },
    { icon: "📊", t: "Escalonamento de processos",
      c: "O escalonador é como o maître de um restaurante: decide qual cliente (processo) será atendido e por quanto tempo. Três níveis: longo prazo (quem entra no restaurante), médio prazo (quem vai para a sala de espera quando lota) e curto prazo (quem é o próximo da fila). As filas incluem job queue (todos os clientes), ready queue (prontos para pedir) e device queues (esperando a conta). A troca de contexto é o tempo de arrumar a mesa entre um cliente e outro. O CFS do Linux busca justiça, como um maître que garante que ninguém espere demais.",
      a: "Crie um programa em Python que simule uma ready queue usando collections.deque. Implemente inserção de processos e remoção para execução. Espera-se uma simulação com 5 processos mostrando a ordem de execução.",
      p: "Pesquise o O(1) scheduler do Linux 2.6 (arrays de prioridade ativos/expired) e o CFS (árvore rubro-negra, vruntime) — compare complexidade, justiça e comportamento interativo.",
      req: ["python3"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Escalonamento de Processos</text><rect x="20" y="40" width="260" height="30" rx="5" fill="#4338ca"/><text x="150" y="60" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Ready Queue: P1 | P2 | P3 | P4 | P5</text><rect x="90" y="85" width="120" height="40" rx="8" fill="#f59e0b"/><text x="150" y="105" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Escalonador</text><rect x="90" y="140" width="120" height="30" rx="5" fill="#059669"/><text x="150" y="160" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">CPU (Executando)</text><line x1="150" y1="70" x2="150" y2="83" stroke="#1e293b" stroke-width="2"/><line x1="150" y1="125" x2="150" y2="138" stroke="#1e293b" stroke-width="2"/></svg>' },
    { icon: "📨", t: "Criação e comunicação entre processos",
      c: "fork() é como uma Xerox que duplica o processo atual (copia tudo: PCB, memória, arquivos abertos). exec() substitui o programa em execução por um novo, como trocar o livro que você está lendo. A comunicação entre processos (IPC) pode ser feita com pipes (como um cano entre duas torneiras), memória compartilhada (um quadro de avisos que todos veem) e message passing (cartas entre processos). Sockets permitem comunicação entre máquinas via rede, como telefonemas entre cidades diferentes.",
      a: "Escreva um programa C onde o pai cria um filho com fork(), envia uma mensagem via pipe com write() e o filho a lê com read() e imprime. Espera-se ver a mensagem trocada entre processos pai e filho no terminal.",
      p: "Pesquise FIFO (named pipes) no Linux com mkfifo e crie dois programas independentes que se comunicam — um escritor e um leitor — executados em terminais separados.",
      req: ["gcc","linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">IPC - Comunicação entre Processos</text><rect x="20" y="40" width="110" height="50" rx="6" fill="#4338ca"/><text x="75" y="62" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Processo Pai</text><text x="75" y="78" text-anchor="middle" fill="#e2e8f0" font-size="8">fork()</text><rect x="170" y="40" width="110" height="50" rx="6" fill="#7c3aed"/><text x="225" y="62" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Processo Filho</text><text x="225" y="78" text-anchor="middle" fill="#e2e8f0" font-size="8">exec()</text><rect x="30" y="110" width="240" height="30" rx="6" fill="#1e293b"/><text x="150" y="130" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Pipe / Memória Compartilhada / Socket</text><rect x="50" y="155" width="80" height="25" rx="4" fill="#2563eb"/><text x="90" y="172" text-anchor="middle" fill="#fff" font-size="9">FIFO</text><rect x="170" y="155" width="80" height="25" rx="4" fill="#059669"/><text x="210" y="172" text-anchor="middle" fill="#fff" font-size="9">Message Queue</text></svg>' },
    { icon: "⏱️", t: "Escalonamento FCFS e SJF",
      c: "FCFS é como uma fila de banco: quem chega primeiro é atendido primeiro. É simples mas sofre do efeito comboio (clientes rápidos presos atrás de um lento). SJF é como atender primeiro quem tem a compra mais rápida no supermercado, minimizando o tempo médio de espera. SJF pode ser preemptivo (SRTF), interrompendo um processo longo quando chega um curto. O problema do SJF é a inanição (starvation): processos longos podem nunca ser atendidos. O aging resolve isso dando prioridade crescente a quem espera muito.",
      a: "Calcule o tempo médio de espera para FCFS e SJF não-preemptivo com processos: P1=6ms (t=0), P2=8ms (t=1), P3=7ms (t=2), P4=3ms (t=3). Monte uma tabela com chegada, burst, início, fim, turnaround e espera de cada processo.",
      p: "Pesquise o problema de starvation no SJF e como o aging (incremento periódico de prioridade) pode resolvê-lo. Compare com o algoritmo HRRN (Highest Response Ratio Next).",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">FCFS vs SJF</text><rect x="20" y="40" width="260" height="35" rx="5" fill="#4338ca"/><text x="150" y="62" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">FCFS: P1 | P2 | P3 | P4 (ordem de chegada)</text><rect x="20" y="85" width="260" height="35" rx="5" fill="#059669"/><text x="150" y="107" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">SJF: P4 | P1 | P3 | P2 (menor burst)</text><rect x="30" y="135" width="240" height="30" rx="6" fill="#f59e0b"/><text x="150" y="155" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">SRTF: SJF Preemptivo</text><text x="150" y="185" text-anchor="middle" fill="#4338ca" font-size="9">Efeito Comboio no FCFS</text></svg>' },
    { icon: "⏲️", t: "Round Robin e Prioridade",
      c: "Round Robin é como uma roda de brinquedos em um parque: cada criança (processo) brinca por um tempo fixo (quantum), depois passa a vez. Se o quantum é pequeno, as trocas são frequentes (muita arrumação). Se é grande, vira FCFS (uma criança monopoliza). Escalonamento por prioridade é como fila VIP: quem tem mais prioridade vai primeiro. A inanição de processos de baixa prioridade é resolvida com aging (aumento gradual da prioridade, como acumular pontos de fidelidade).",
      a: "Simule Round Robin com quantum=4ms para P1(9ms), P2(5ms), P3(3ms), P4(7ms) chegando em t=0. Desenhe o diagrama de Gantt e calcule turnaround médio e tempo de espera médio.",
      p: "Pesquise como o Windows implementa prioridades: 32 níveis (0-31), classe de prioridade (Idle, Normal, High, Realtime) e prioridade relativa (AboveNormal, BelowNormal).",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Round Robin</text><circle cx="150" cy="65" r="40" fill="none" stroke="#4338ca" stroke-width="3"/><rect x="110" y="25" width="80" height="25" rx="4" fill="#4338ca"/><text x="150" y="42" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">P1 (9ms)</text><rect x="195" y="50" width="80" height="25" rx="4" fill="#7c3aed"/><text x="235" y="67" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">P2 (5ms)</text><rect x="185" y="88" width="80" height="25" rx="4" fill="#2563eb"/><text x="225" y="105" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">P3 (3ms)</text><rect x="35" y="88" width="80" height="25" rx="4" fill="#059669"/><text x="75" y="105" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">P4 (7ms)</text><text x="150" y="150" text-anchor="middle" fill="#4338ca" font-size="10" font-weight="bold">Quantum = 4ms</text><rect x="50" y="165" width="200" height="20" rx="3" fill="#1e293b"/><text x="150" y="179" text-anchor="middle" fill="#fff" font-size="8">Escalonamento por Prioridade (32 níveis)</text></svg>' },
    { icon: "📶", t: "Escalonamento Multinível",
      c: "Filas multinível são como um aeroporto com filas separadas: primeira classe (prioridade máxima, RR rápido), classe executiva (RR médio) e econômica (FCFS, mais devagar). Multilevel Feedback Queue (MFQ) permite que processos mudem de fila: um processo que usa muita CPU cai para filas mais lentas, enquanto processos interativos (que usam pouca CPU) sobem. O MFQ é usado por sistemas BSD Unix com 32 filas e prioridades que decaem com o tempo.",
      a: "Desenhe um diagrama com 3 filas multinível: sistema (RR q=2ms), interativo (RR q=8ms) e batch (FCFS). Explique como um processo interativo (pouco burst) e um batch (burst longo) seriam tratados. Espera-se um diagrama mostrando as filas com setas de migração.",
      p: "Pesquise o escalonador 4.4BSD que usa multilevel feedback com 32 filas, prioridades decaindo a cada 0.1s e política de envelhecimento para evitar starvation.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Filas Multinível</text><rect x="30" y="40" width="240" height="35" rx="5" fill="#4338ca"/><text x="150" y="62" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Fila Sistema: RR q=2ms (maior prioridade)</text><rect x="30" y="80" width="240" height="35" rx="5" fill="#7c3aed"/><text x="150" y="102" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Fila Interativa: RR q=8ms</text><rect x="30" y="120" width="240" height="35" rx="5" fill="#2563eb"/><text x="150" y="142" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Fila Batch: FCFS (menor prioridade)</text><text x="150" y="180" text-anchor="middle" fill="#4338ca" font-size="9">Multilevel Feedback Queue (MFQ) - migração entre filas</text></svg>' },
    { icon: "🧵", t: "Threads",
      c: "Thread é como um funcionário dentro de um departamento (processo): todos compartilham o mesmo escritório (espaço de endereço: código, dados, heap) mas cada um tem sua própria mesa (pilha e registradores). Três modelos: muitos-para-um (N:1, vários funcionários mas um telefone só), um-para-um (1:1, cada funcionário com seu telefone, ex: Linux NPTL), e muitos-para-muitos (N:M, híbrido). Threads são mais leves que processos: criar uma thread é ~10x mais rápido. POSIX Threads (pthreads) é a API padrão em Unix.",
      a: "Crie um programa com pthreads que lance 5 threads. Cada thread deve imprimir seu ID e uma iteração de 0 a 9 com usleep(100000). Espera-se ver a saída intercalada das threads demonstrando concorrência.",
      p: "Pesquise user-level threads (green threads, fibras) vs kernel-level threads — vantagens (troca sem syscall, escalonamento customizado) e desvantagens (bloqueio em syscall, sem paralelismo real).",
      req: ["gcc","linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Threads</text><rect x="100" y="30" width="100" height="40" rx="6" fill="#4338ca"/><text x="150" y="55" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Processo</text><rect x="30" y="85" width="70" height="30" rx="4" fill="#059669"/><text x="65" y="105" text-anchor="middle" fill="#fff" font-size="8">Thread 1</text><rect x="115" y="85" width="70" height="30" rx="4" fill="#059669"/><text x="150" y="105" text-anchor="middle" fill="#fff" font-size="8">Thread 2</text><rect x="200" y="85" width="70" height="30" rx="4" fill="#059669"/><text x="235" y="105" text-anchor="middle" fill="#fff" font-size="8">Thread 3</text><rect x="30" y="125" width="240" height="25" rx="4" fill="#1e293b"/><text x="150" y="142" text-anchor="middle" fill="#fff" font-size="9">Memória Compartilhada (código + dados + heap)</text><text x="150" y="180" text-anchor="middle" fill="#4338ca" font-size="9">pthreads / NPTL (Linux) - 1:1 kernel-level</text></svg>' },
    { icon: "🔒", t: "Sincronização — Seção Crítica",
      c: "Race condition é como dois cozinheiros tentando usar a mesma faca ao mesmo tempo — o resultado depende de quem pega primeiro. A seção crítica é o trecho de código que acessa o recurso compartilhado (a faca). Quatro condições ideais: exclusão mútua (só um por vez), progresso (quem decide é quem está esperando), espera limitada (ninguém espera para sempre) e sem suposições sobre velocidade. Algoritmo de Peterson resolve para dois processos. Instruções atômicas TestAndSet e Swap são soluções de hardware.",
      a: "Implemente o algoritmo de Peterson em C para sincronizar 2 threads que incrementam um contador compartilhado 10000 vezes cada. Compare com e sem sincronização. Espera-se que sem sincronização o contador seja incorreto (< 20000).",
      p: "Pesquise as instruções atômicas xchg (x86, troca registrador com memória) e ldxr/stxr (ARM, load-link/store-conditional) usadas para implementar spinlocks e mutex no kernel.",
      req: ["gcc","linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Seção Crítica</text><rect x="30" y="40" width="110" height="50" rx="6" fill="#4338ca"/><text x="85" y="62" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Thread A</text><text x="85" y="78" text-anchor="middle" fill="#e2e8f0" font-size="8">entra na SC</text><rect x="160" y="40" width="110" height="50" rx="6" fill="#7c3aed"/><text x="215" y="62" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Thread B</text><text x="215" y="78" text-anchor="middle" fill="#e2e8f0" font-size="8">espera</text><rect x="55" y="105" width="190" height="35" rx="6" fill="#f59e0b"/><text x="150" y="127" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Recurso Compartilhado</text><rect x="30" y="155" width="240" height="25" rx="5" fill="#1e293b"/><text x="150" y="172" text-anchor="middle" fill="#fff" font-size="9">Peterson / TSL / XCHG - Exclusão Mútua</text></svg>' },
    { icon: "🚦", t: "Semáforos e Monitores",
      c: "Semáforo é como uma senha de balcão: wait() pega uma senha (se acabou, espera) e signal() devolve a senha (acorda quem espera). Mutex é um semáforo binário, como uma chave de banheiro químico (só um por vez). Semáforos contadores controlam múltiplas instâncias, como vagas em um estacionamento. Monitor é como um segurança de festa que controla automaticamente quem entra e sai. Em Java (synchronized) e Python (threading.Condition), monitores simplificam a programação concorrente.",
      a: "Resolva o problema dos leitores-escritores usando semáforos em C ou Python. Leitores podem ler simultaneamente; escritores têm acesso exclusivo. Implemente usando mutex e semáforo contador. Espera-se um programa funcional com threads leitoras e escritoras.",
      p: "Pesquise as funções pthread_mutex_lock, pthread_mutex_unlock, pthread_cond_wait e pthread_cond_signal do POSIX Threads. Explique o funcionamento de variáveis de condição com mutex.",
      req: ["gcc","linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Semáforos e Monitores</text><rect x="30" y="40" width="110" height="45" rx="6" fill="#4338ca"/><text x="85" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">wait(S)</text><text x="85" y="76" text-anchor="middle" fill="#e2e8f0" font-size="8">decrementa</text><rect x="160" y="40" width="110" height="45" rx="6" fill="#059669"/><text x="215" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">signal(S)</text><text x="215" y="76" text-anchor="middle" fill="#e2e8f0" font-size="8">incrementa</text><rect x="55" y="100" width="190" height="35" rx="6" fill="#f59e0b"/><text x="150" y="122" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Mutex (semáforo binário)</text><rect x="30" y="148" width="240" height="30" rx="6" fill="#1e293b"/><text x="150" y="168" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Monitor: sincronizado / Condition</text></svg>' },
    { icon: "🍽️", t: "Problemas clássicos de sincronização",
      c: "Três problemas clássicos. Produtor-Consumidor: um chef (produtor) coloca pratos em uma esteira (buffer) e um garçom (consumidor) os retira, usando semáforos para controlar vagas e itens. Leitores-Escritores: leitores consultam um quadro de avisos simultaneamente, mas escritores precisam apagar tudo e reescrever sozinhos. Jantar dos Filósofos (Dijkstra, 1965): 5 filósofos precisam de 2 hashis para comer. Se todos pegarem o hashi esquerdo ao mesmo tempo, ninguém come (deadlock). Solução: ímpares pegam esquerdo, pares pegam direito.",
      a: "Implemente o Jantar dos Filósofos em C com pthreads e semáforos. Use a solução assimétrica para evitar deadlock. Espera-se que os 5 filósofos comam e pensem indefinidamente sem travar.",
      p: "Pesquise a solução de Tanenbaum para o Jantar dos Filósofos usando estados (PENSANDO, COM_FOME, COMENDO) e a função test() que verifica deadlock antes de permitir comer.",
      req: ["gcc","linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Problemas Clássicos</text><rect x="15" y="40" width="85" height="45" rx="6" fill="#4338ca"/><text x="57" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Produtor</text><text x="57" y="76" text-anchor="middle" fill="#e2e8f0" font-size="8">Consumidor</text><rect x="108" y="40" width="85" height="45" rx="6" fill="#059669"/><text x="150" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Leitores</text><text x="150" y="76" text-anchor="middle" fill="#e2e8f0" font-size="8">Escritores</text><rect x="200" y="40" width="85" height="45" rx="6" fill="#f59e0b"/><text x="242" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Jantar dos</text><text x="242" y="76" text-anchor="middle" fill="#e2e8f0" font-size="8">Filósofos</text><rect x="30" y="105" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="127" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Buffer Limitado / Semáforos</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="9">Solução: assimétrica ou semáforo de garçom</text></svg>' },
    { icon: "💀", t: "Deadlocks — caracterização",
      c: "Deadlock é como um engarrafamento em um cruzamento onde cada carro espera o outro sair. Quatro condições necessárias (Coffman, 1971): Mutex (rua de mão única), Posse e Espera (carro ocupa cruzamento e espera), Não-Preempção (ninguém pode rebocar), Espera Circular (cada carro espera o da frente). O grafo de alocação (RAG) representa isso visualmente: círculos são processos, quadrados são recursos. Um ciclo no grafo indica deadlock se cada recurso tem apenas uma instância.",
      a: "Dado um sistema com 3 processos (P1,P2,P3) e 2 recursos (R1 com 1 instância, R2 com 1 instância), desenhe o grafo de alocação para um cenário com deadlock. Identifique o ciclo e explique qual condição de Coffman poderia ser quebrada.",
      p: "Pesquise o deadlock no Therac-25 (acidente de radioterapia 1985-87) causado por race condition em variável compartilhada — exemplo real de falha de sincronização com consequências fatais.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Deadlock - 4 Condições de Coffman</text><rect x="15" y="40" width="130" height="30" rx="5" fill="#dc2626"/><text x="80" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">1. Exclusão Mútua</text><rect x="155" y="40" width="130" height="30" rx="5" fill="#dc2626"/><text x="220" y="60" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">2. Posse e Espera</text><rect x="15" y="80" width="130" height="30" rx="5" fill="#dc2626"/><text x="80" y="100" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">3. Não-Preempção</text><rect x="155" y="80" width="130" height="30" rx="5" fill="#dc2626"/><text x="220" y="100" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">4. Espera Circular</text><rect x="50" y="130" width="200" height="35" rx="6" fill="#1e293b"/><text x="150" y="152" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Grafo de Alocação (RAG)</text></svg>' },
    { icon: "🔓", t: "Tratamento de deadlocks",
      c: "Quatro estratégias contra deadlocks. Prevenção: quebrar uma condição de Coffman, como alocar todos os recursos de uma vez (já pega tudo que precisa) ou ordenar recursos (todos pegam na mesma ordem). Evitação: algoritmo do Banqueiro (Dijkstra), que simula se a liberação dos recursos é possível antes de emprestar. Detecção: verificar ciclos no grafo de alocação O(n²). Recuperação: matar processos no deadlock (fechar programas) ou preemptar recursos (forçar liberação). Sistemas modernos usam combinação dessas estratégias.",
      a: "Implemente o algoritmo do Banqueiro em Python para 5 processos e 3 tipos de recurso. Leia alocação atual e máxima, calcule Available e verifique se o estado é seguro. Espera-se uma sequência segura como saída.",
      p: "Pesquise o lockdep do Linux — ferramenta que mapeia dependências entre locks no kernel e emite avisos ao detectar ciclos potenciais de deadlock.",
      req: ["python3"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Estratégias contra Deadlock</text><rect x="15" y="40" width="60" height="45" rx="5" fill="#4338ca"/><text x="45" y="58" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Prev.</text><text x="45" y="74" text-anchor="middle" fill="#e2e8f0" font-size="7">Quebrar</text><rect x="85" y="40" width="60" height="45" rx="5" fill="#059669"/><text x="115" y="58" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Evit.</text><text x="115" y="74" text-anchor="middle" fill="#e2e8f0" font-size="7">Banqueiro</text><rect x="155" y="40" width="60" height="45" rx="5" fill="#f59e0b"/><text x="185" y="58" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Det.</text><text x="185" y="74" text-anchor="middle" fill="#e2e8f0" font-size="7">Ciclo</text><rect x="225" y="40" width="60" height="45" rx="5" fill="#dc2626"/><text x="255" y="58" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Rec.</text><text x="255" y="74" text-anchor="middle" fill="#e2e8f0" font-size="7">Matar</text><rect x="40" y="105" width="220" height="35" rx="6" fill="#1e293b"/><text x="150" y="127" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Algoritmo do Banqueiro</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="9">lockdep do Linux - detecta ciclo de locks</text></svg>' },
    { icon: "🧪", t: "Prática: threads em C/Python",
      c: "Laboratório prático de programação concorrente. Criação de threads com pthread_create (função e argumento). Sincronização com mutex (pthread_mutex_lock/unlock) e semáforos (sem_wait/sem_post). Problemas: soma paralela de vetor (dividir entre N threads como dividir uma conta de restaurante), produtor-consumidor com buffer circular. Depuração com gdb (thread apply all bt para ver todas as threads). Análise com helgrind (Valgrind) detecta race conditions. Speedup limitado pela Lei de Amdahl (sempre há parte sequencial).",
      a: "Implemente em C soma paralela de vetor de 10 milhões de inteiros dividindo entre 4 threads. Compare com versão sequencial (clock_gettime). Espera-se speedup entre 2x e 3x dado overhead de criação e sincronização.",
      p: "Pesquise um bug histórico de race condition: Therac-25 (1985) ou bug do DNS NTP (2014, getrandom causou timeout em massa). Explique causa raiz e correção.",
      req: ["gcc","linux","valgrind"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Prática: Threads</text><rect x="30" y="40" width="240" height="35" rx="6" fill="#4338ca"/><text x="150" y="62" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">pthread_create / pthread_join</text><rect x="30" y="85" width="110" height="35" rx="5" fill="#059669"/><text x="85" y="107" text-anchor="middle" fill="#fff" font-size="9">Mutex lock/unlock</text><rect x="160" y="85" width="110" height="35" rx="5" fill="#f59e0b"/><text x="215" y="107" text-anchor="middle" fill="#fff" font-size="9">Semáforos</text><rect x="30" y="135" width="240" height="30" rx="6" fill="#1e293b"/><text x="150" y="155" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Valgrind helgrind / gdb</text><text x="150" y="185" text-anchor="middle" fill="#4338ca" font-size="9">Lei de Amdahl: speedup limitado</text></svg>' },
    { icon: "🧪", t: "Prática: simulação de escalonamento",
      c: "Implementar um simulador de escalonamento que lê processos (nome, chegada, burst, prioridade) e aplica FCFS, SJF, RR (quantum ajustável) e Prioridade. Calcular métricas: turnaround (hora de saída − hora de chegada), espera (turnaround − burst), throughput (processos por tempo total) e utilização da CPU. Gerar diagrama de Gantt textual para visualização. Entrada via arquivo CSV ou linha de comando. Saída em tabela para comparação entre algoritmos.",
      a: "Crie simulador em Python com entrada CSV implementando FCFS, SJF (preemptivo e não), RR e Prioridade. Gere Gantt textual e tabela com métricas. Espera-se comparação clara entre algoritmos para o mesmo conjunto de processos.",
      p: "Pesquise o Scheduling Simulator do livro Operating System Concepts (Silberschatz) como referência de implementação — modelo de filas e cálculo de métricas.",
      req: ["python3"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Simulador de Escalonamento</text><rect x="20" y="40" width="260" height="30" rx="5" fill="#4338ca"/><text x="150" y="60" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Entrada: processos.csv (nome, chegada, burst)</text><rect x="20" y="80" width="80" height="30" rx="4" fill="#059669"/><text x="60" y="100" text-anchor="middle" fill="#fff" font-size="8">FCFS</text><rect x="110" y="80" width="80" height="30" rx="4" fill="#059669"/><text x="150" y="100" text-anchor="middle" fill="#fff" font-size="8">SJF</text><rect x="200" y="80" width="80" height="30" rx="4" fill="#059669"/><text x="240" y="100" text-anchor="middle" fill="#fff" font-size="8">RR</text><rect x="30" y="125" width="240" height="30" rx="6" fill="#f59e0b"/><text x="150" y="145" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Turnaround / Espera / Throughput</text><rect x="50" y="165" width="200" height="20" rx="4" fill="#1e293b"/><text x="150" y="179" text-anchor="middle" fill="#fff" font-size="8">Diagrama de Gantt</text></svg>' },
    { icon: "📝", t: "Prova 1",
      c: "Avaliação individual do primeiro bimestre. Tópicos: processos (PCB, estados, troca de contexto), threads (modelos, pthreads), escalonamento (FCFS, SJF, RR, Prioridade, Multinível), sincronização (seção crítica, semáforos, monitores, problemas clássicos) e deadlocks (condições de Coffman, grafo, banqueiro). Questões discursivas, cálculos de turnaround/espera e análise de código concorrente. Duração: 50 minutos. Consulta: apenas anotações impressas.",
      a: "Resolva a prova em 50 minutos. Gerencie o tempo: comece pelas questões que domina. Leia cada enunciado com atenção antes de responder.",
      p: "Após a prova, revise as questões com dificuldade e aprofunde com base no livro do Silberschatz (capítulos 3-7) para a prova final.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "🧠", t: "Conceitos de gerência de memória",
      c: "Hierarquia de memória é como uma escrivaninha: registradores são os papéis na sua mão (ns, bytes), cache L1/L2/L3 são as gavetas mais próximas (ns, KB-MB), RAM é a estante ao lado (dezenas de ns, GB) e disco é o arquivo no porão (ms, TB). Cada nível é maior, mais lento e mais barato. Endereço lógico é o nome do documento; endereço físico é onde ele realmente está na estante. A MMU traduz um no outro usando TLB (cache de traduções) e tabela de páginas.",
      a: "Use cat /proc/cpuinfo para ver tamanhos de cache L1d, L1i, L2 e L3 do processador. Depois free -h para RAM total e usada. Espera-se registrar valores e identificar a hierarquia.",
      p: "Pesquise a hierarquia de memória de um Intel Core i7-13700K: tamanhos de cache L1, L2 (por núcleo) e L3 (compartilhado), latências em ciclos e largura de banda.",
      req: ["linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Hierarquia de Memória</text><rect x="60" y="30" width="180" height="22" rx="3" fill="#4338ca"/><text x="150" y="46" text-anchor="middle" fill="#fff" font-size="8" font-weight="bold">Registradores (ns)</text><rect x="40" y="58" width="220" height="22" rx="3" fill="#7c3aed"/><text x="150" y="74" text-anchor="middle" fill="#fff" font-size="8" font-weight="bold">Cache L1 / L2 / L3 (ns ~ KB-MB)</text><rect x="20" y="86" width="260" height="22" rx="3" fill="#2563eb"/><text x="150" y="102" text-anchor="middle" fill="#fff" font-size="8" font-weight="bold">Memória RAM (dezenas de ns ~ GB)</text><rect x="50" y="120" width="200" height="25" rx="3" fill="#1e293b"/><text x="150" y="137" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Disco (ms ~ TB)</text><text x="150" y="180" text-anchor="middle" fill="#4338ca" font-size="9">MMU + TLB: endereço lógico → físico</text></svg>' },
    { icon: "📦", t: "Alocação contígua",
      c: "Particionamento fixo é como um estacionamento com vagas de tamanhos fixos: simples mas desperdiça espaço se o carro for menor que a vaga (fragmentação interna). Particionamento variável aloca o tamanho exato, sem desperdício interno mas com buracos entre os carros (fragmentação externa). Swapping move processos entre RAM e disco, como guardar malas no porta-malas. Compactação reorganiza tudo para juntar espaços livres. Algoritmos: first-fit (primeira vaga que cabe), best-fit (menor vaga) e worst-fit (maior vaga).",
      a: "Simule gerenciador de memória com partições variáveis em Python. Implemente alocar(tamanho) e liberar(endereço) com first-fit. Mostre estado da memória após cada operação evidenciando fragmentação externa.",
      p: "Pesquise o buddy system (sistema de parceiros) do Linux para alocação de páginas: divide blocos em metades até o tamanho desejado, coalesce blocos adjacentes rapidamente.",
      req: ["python3"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Alocação Contígua</text><rect x="20" y="35" width="260" height="20" rx="3" fill="#4338ca"/><text x="150" y="49" text-anchor="middle" fill="#fff" font-size="8">Particionamento Fixo</text><rect x="20" y="60" width="100" height="25" rx="3" fill="#4338ca"/><text x="70" y="78" text-anchor="middle" fill="#fff" font-size="8">Part 1</text><rect x="125" y="60" width="80" height="25" rx="3" fill="#7c3aed"/><text x="165" y="78" text-anchor="middle" fill="#fff" font-size="8">Part 2</text><rect x="210" y="60" width="70" height="25" rx="3" fill="#2563eb"/><text x="245" y="78" text-anchor="middle" fill="#fff" font-size="8">Part 3</text><text x="150" y="105" text-anchor="middle" fill="#4338ca" font-size="9">Fragmentação interna x externa</text><rect x="30" y="120" width="240" height="30" rx="6" fill="#1e293b"/><text x="150" y="140" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">First-fit / Best-fit / Worst-fit</text><text x="150" y="180" text-anchor="middle" fill="#4338ca" font-size="9">Buddy system (Linux) - coalesce parceiros</text></svg>' },
    { icon: "🧩", t: "Segmentação",
      c: "Segmentação divide a memória em pedaços lógicos como as seções de um escritório: código (a planta baixa), dados (os móveis), pilha (as caixas empilhadas) e heap (a área de expansão). Cada segmento tem nome, base (onde começa na memória física) e limite (tamanho). A tabela de segmentos mapeia segmento + offset para endereço físico. Vantagem: reflete a organização lógica do programa. Desvantagem: fragmentação externa. No x86-64 a segmentação é mínima — o sistema usa paginação pura.",
      a: "Dada tabela de segmentos: S0: base=1400 limite=800; S1: base=6300 limite=400; S2: base=4300 limite=1100. Calcule endereço físico para (0,350), (1,230) e (2,1200). Identifique illegal access onde offset > limite.",
      p: "Pesquise a segmentação no modo protegido do x86-32: registradores CS/DS/ES/FS/GS/SS, descritores (GDT/LDT) e níveis de privilégio RING 0-3. No x86-64 a segmentação é essencialmente desabilitada.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Segmentação</text><rect x="30" y="35" width="60" height="30" rx="4" fill="#4338ca"/><text x="60" y="55" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Código</text><rect x="100" y="35" width="60" height="30" rx="4" fill="#059669"/><text x="130" y="55" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Dados</text><rect x="170" y="35" width="60" height="30" rx="4" fill="#f59e0b"/><text x="200" y="55" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Pilha</text><rect x="45" y="80" width="210" height="30" rx="5" fill="#1e293b"/><text x="150" y="100" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Tabela de Segmentos</text><text x="150" y="135" text-anchor="middle" fill="#4338ca" font-size="9">Segmento: nome / base / limite</text><text x="150" y="155" text-anchor="middle" fill="#4338ca" font-size="9">x86-64: segmentação desabilitada</text><text x="150" y="180" text-anchor="middle" fill="#4338ca" font-size="9">Usa paginação pura</text></svg>' },
    { icon: "📄", t: "Paginação",
      c: "Memória virtual é como um arquivo digital: o programa enxerga um espaço enorme (endereço lógico) que não precisa existir todo na RAM. Paginação divide esse espaço em páginas (4KB no Linux x86-64) e a RAM em quadros do mesmo tamanho, como dividir um quebra-cabeça em peças. A tabela de páginas (uma por processo) mapeia página lógica → quadro físico. TLB é o cache dessas traduções na MMU: TLB miss custa dezenas de ciclos. Paginação elimina fragmentação externa mas tem desperdício interno na última página.",
      a: "Use cat /proc/meminfo para MemTotal, MemFree, SwapTotal, SwapFree. Escreva programa C que aloque 100MB com malloc+memset e observe com vmstat 1 o aumento de memória virtual e RSS. Correlacione alocação com vmstat.",
      p: "Pesquise TLB misses: custo de 10-100 ciclos, impacto em big data, e como huge pages (2MB/1GB no Linux) reduzem TLB misses para aplicações com grande consumo de memória.",
      req: ["linux","gcc"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Paginação</text><rect x="20" y="35" width="120" height="35" rx="5" fill="#4338ca"/><text x="80" y="57" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Página Lógica</text><rect x="160" y="35" width="120" height="35" rx="5" fill="#059669"/><text x="220" y="57" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Quadro Físico</text><rect x="30" y="85" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="107" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Tabela de Páginas (por processo)</text><rect x="30" y="130" width="110" height="30" rx="5" fill="#f59e0b"/><text x="85" y="150" text-anchor="middle" fill="#fff" font-size="9">TLB (cache MMU)</text><rect x="160" y="130" width="110" height="30" rx="5" fill="#2563eb"/><text x="215" y="150" text-anchor="middle" fill="#fff" font-size="9">4KB por página</text><text x="150" y="185" text-anchor="middle" fill="#4338ca" font-size="9">Huge Pages (2MB/1GB) - menos TLB misses</text></svg>' },
    { icon: "📏", t: "Alocação de quadros e thrashing",
      c: "Alocação de quadros: fixa (cada processo tem limite máximo) ou variável (cresce conforme necessidade). Algoritmos de substituição: FIFO (joga fora o mais antigo, como fila de mercado — anomalia de Belady mostra que mais quadros podem piorar), LRU (menos recentemente usado, como limpar o que não usamos há mais tempo) e Ótimo (sabe o futuro, referência teórica). Thrashing é quando o sistema gasta mais tempo paginando que executando, como um escritório onde todo mundo fica procurando arquivos em vez de trabalhar.",
      a: "Simule FIFO, LRU e Ótimo para sequência: 7,0,1,2,0,3,0,4,2,3,0,3,2,1,0,7 com 3 quadros. Conte page faults de cada. Espera-se FIFO mais faults, LRU intermediário, Ótimo mínimo.",
      p: "Pesquise o working-set model de Denning (1968): conjunto de páginas que processo usa ativamente (WSSi). SO monitora working-set e só escala processos se houver RAM suficiente para evitar thrashing.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Substituição de Páginas</text><rect x="20" y="35" width="60" height="30" rx="4" fill="#4338ca"/><text x="50" y="55" text-anchor="middle" fill="#fff" font-size="9">FIFO</text><rect x="90" y="35" width="60" height="30" rx="4" fill="#059669"/><text x="120" y="55" text-anchor="middle" fill="#fff" font-size="9">LRU</text><rect x="160" y="35" width="60" height="30" rx="4" fill="#f59e0b"/><text x="190" y="55" text-anchor="middle" fill="#fff" font-size="9">NRU</text><rect x="230" y="35" width="60" height="30" rx="4" fill="#2563eb"/><text x="260" y="55" text-anchor="middle" fill="#fff" font-size="9">Ótimo</text><rect x="30" y="85" width="240" height="35" rx="6" fill="#dc2626"/><text x="150" y="107" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Thrashing: mais paginação que execução</text><rect x="50" y="135" width="200" height="30" rx="6" fill="#1e293b"/><text x="150" y="155" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Working-Set Model (Denning)</text></svg>' },
    { icon: "🐧", t: "Memória virtual na prática",
      c: "Ferramentas Linux para memória. /proc/meminfo: estatísticas (MemTotal, MemFree, Buffers, Cached, SwapTotal). vmstat 1: relatório com processos (r,b), memória (swpd,free,buff,cache), swap (si,so) e CPU (us,sy,id,wa). free -h: resumo RAM+swap. Kernel Linux usa LRU aproximado com active_list (páginas acessadas recentemente) e inactive_list (candidatas a swap). OOM Killer: ativado quando a memória acaba, escolhe um processo para matar baseado em oom_score (badness).",
      a: "Execute vmstat 1 por 10s enquanto abre programas. Observe si (swap in) e so (swap out). Depois free -h. Espera-se interpretar campos de vmstat e free, identificando se há swapping ativo.",
      p: "Pesquise o OOM Killer: cálculo de oom_score (memória, tempo de vida, oom_adj) e configuração de /proc/PID/oom_adj para proteger processos críticos de serem mortos.",
      req: ["linux","procps"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Memória Virtual - Prática</text><rect x="20" y="35" width="120" height="30" rx="5" fill="#4338ca"/><text x="80" y="55" text-anchor="middle" fill="#fff" font-size="9">/proc/meminfo</text><rect x="160" y="35" width="120" height="30" rx="5" fill="#059669"/><text x="220" y="55" text-anchor="middle" fill="#fff" font-size="9">vmstat 1</text><rect x="20" y="75" width="120" height="30" rx="5" fill="#7c3aed"/><text x="80" y="95" text-anchor="middle" fill="#fff" font-size="9">free -h</text><rect x="160" y="75" width="120" height="30" rx="5" fill="#f59e0b"/><text x="220" y="95" text-anchor="middle" fill="#fff" font-size="9">OOM Killer</text><rect x="30" y="120" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="142" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">active_list / inactive_list (LRU)</text><text x="150" y="180" text-anchor="middle" fill="#4338ca" font-size="9">oom_score: badness do processo</text></svg>' },
    { icon: "📁", t: "Conceitos e diretórios",
      c: "Arquivo é como um documento em um escritório: tem nome, tipo e metadados (tamanho, permissões, dono, timestamps). Diretórios organizam documentos em pastas em formato de árvore. No Unix, permissões são rwx (ler, escrever, executar) para dono/grupo/outros. Link count mostra quantos atalhos (hard links) apontam para o mesmo documento. Links simbólicos (ln -s) são como atalhos de desktop que apontam para outro caminho — se o original for movido, o atalho quebra.",
      a: "Use stat para metadados (Device, Inode, Links, Access, Modify, Change). ls -la para permissões. Crie link simbólico com ln -s. Explique cada campo: permissões (octal e rwx), inode, hard vs soft links.",
      p: "Pesquise hard links (mesmo inode, não cruzam filesystems, não apontam para diretórios) vs soft links (arquivo com caminho, podem falhar se alvo removido, cruzam filesystems).",
      req: ["linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Diretórios e Arquivos</text><rect x="110" y="30" width="80" height="25" rx="4" fill="#4338ca"/><text x="150" y="47" text-anchor="middle" fill="#fff" font-size="9">/ (raiz)</text><rect x="30" y="60" width="70" height="22" rx="3" fill="#059669"/><text x="65" y="75" text-anchor="middle" fill="#fff" font-size="8">/home</text><rect x="110" y="60" width="70" height="22" rx="3" fill="#059669"/><text x="145" y="75" text-anchor="middle" fill="#fff" font-size="8">/etc</text><rect x="190" y="60" width="70" height="22" rx="3" fill="#059669"/><text x="225" y="75" text-anchor="middle" fill="#fff" font-size="8">/var</text><rect x="60" y="90" width="60" height="20" rx="3" fill="#f59e0b"/><text x="90" y="104" text-anchor="middle" fill="#fff" font-size="7">usuario/</text><rect x="140" y="90" width="60" height="20" rx="3" fill="#f59e0b"/><text x="170" y="104" text-anchor="middle" fill="#fff" font-size="7">ssh/</text><rect x="50" y="125" width="200" height="30" rx="6" fill="#1e293b"/><text x="150" y="145" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Inode: permissoes / dono / links</text><text x="150" y="182" text-anchor="middle" fill="#4338ca" font-size="9">stat / ls -la / ln -s (soft link)</text></svg>' },
    { icon: "💾", t: "Implementação de sistemas de arquivos",
      c: "Estruturas no disco: boot block (instruções de inicialização, como o manual de partida), superblock (metadados do FS: número de inodes, blocos livres, tamanho do bloco), inodes (ficha de cada arquivo: permissões, dono, tamanho, ponteiros para blocos), blocos de dados (conteúdo real). Alocação: contígua (sequencial como páginas de um livro), encadeada (FAT, cada bloco aponta ao próximo), indexada (inodes Unix com ponteiros diretos/indiretos). Ext4 usa extents (intervalos contíguos) para maior eficiência.",
      a: "Crie sistema de arquivos simples em Python simulando disco em arquivo binário. Suporte criar, ler, escrever e deletar arquivos com struct.pack para serializar superblock e inodes. Operações persistentes no arquivo de disco.",
      p: "Pesquise ext4: journaling (metadados + dados), extent tree (B-tree de extents), inline data (dados no inode), flex_bg (agrupar metadados) e tune2fs para configurar parâmetros.",
      req: ["python3"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Estrutura do Sistema de Arquivos</text><rect x="15" y="35" width="55" height="30" rx="4" fill="#4338ca"/><text x="42" y="55" text-anchor="middle" fill="#fff" font-size="8">Boot</text><rect x="80" y="35" width="55" height="30" rx="4" fill="#059669"/><text x="107" y="55" text-anchor="middle" fill="#fff" font-size="8">Superblock</text><rect x="145" y="35" width="55" height="30" rx="4" fill="#f59e0b"/><text x="172" y="55" text-anchor="middle" fill="#fff" font-size="8">Inodes</text><rect x="210" y="35" width="55" height="30" rx="4" fill="#2563eb"/><text x="237" y="55" text-anchor="middle" fill="#fff" font-size="8">Dados</text><rect x="30" y="85" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="107" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Ext4: extent tree + journaling</text><text x="150" y="145" text-anchor="middle" fill="#4338ca" font-size="9">Alocação: contígua / encadeada / indexada</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="9">tune2fs: ajustar parametros do FS</text></svg>' },
    { icon: "🔗", t: "Montagem e gerenciamento",
      c: "Montagem (mount) é como pendurar uma nova estante na parede: o sistema de arquivos fica acessível no ponto de montagem (ex: /mnt/usb). Journaling (ext3, ext4, NTFS) registra operações em um diário antes de executar — se o sistema cair, o diário é reproduzido para consistência, evitando o demorado fsck. LVM redimensiona volumes sem reparticionar, tira snapshots e combina discos. RAID combina discos: RAID 0 (striping, mais velocidade), RAID 1 (espelho, segurança), RAID 5 (paridade, equilíbrio).",
      a: "Execute mount para listar sistemas montados. df -hT para ponto, tipo (ext4, xfs, ntfs), tamanho, usado, disponível. Identifique ao menos 3 tipos diferentes de sistemas de arquivos montados.",
      p: "Pesquise níveis de RAID (0,1,5,6,10): discos mínimos, tolerância a falhas, overhead e desempenho leitura/escrita. Compare RAID 5 vs RAID 6 para servidores de arquivos.",
      req: ["linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Montagem e Gerenciamento</text><rect x="20" y="35" width="260" height="30" rx="5" fill="#4338ca"/><text x="150" y="55" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">mount /mnt/usb - integra FS na árvore</text><rect x="20" y="75" width="120" height="30" rx="5" fill="#059669"/><text x="80" y="95" text-anchor="middle" fill="#fff" font-size="9">Journaling (ext3/4)</text><rect x="160" y="75" width="120" height="30" rx="5" fill="#7c3aed"/><text x="220" y="95" text-anchor="middle" fill="#fff" font-size="9">LVM</text><rect x="20" y="115" width="55" height="30" rx="4" fill="#2563eb"/><text x="47" y="135" text-anchor="middle" fill="#fff" font-size="8">RAID 0</text><rect x="85" y="115" width="55" height="30" rx="4" fill="#2563eb"/><text x="112" y="135" text-anchor="middle" fill="#fff" font-size="8">RAID 1</text><rect x="150" y="115" width="55" height="30" rx="4" fill="#2563eb"/><text x="177" y="135" text-anchor="middle" fill="#fff" font-size="8">RAID 5</text><rect x="215" y="115" width="55" height="30" rx="4" fill="#2563eb"/><text x="242" y="135" text-anchor="middle" fill="#fff" font-size="8">RAID 10</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="9">df -hT / mount</text></svg>' },
    { icon: "🔌", t: "Hardware e subsistema de E/S",
      c: "Controladores são chips que comandam dispositivos (SATA, NVMe, USB). Polling é como perguntar repetidamente se a comida ficou pronta — simples mas desperdiça tempo. Interrupções são como a campainha do forno: o dispositivo avisa a CPU quando termina a operação (IRQ). DMA é um assistente que transfere dados diretamente entre dispositivo e memória sem incomodar a CPU. NVMe e GPUs usam PCIe DMA para milhões de operações por segundo. MSI-X permite interrupções direcionadas a núcleos específicos.",
      a: "Execute cat /proc/interrupts para listar interrupções desde boot. Identifique dispositivos com mais IRQs: timer (IRQ 0), teclado (IRQ 1), GPU, controladora de disco. Reconheça IRQs de dispositivos PCIe.",
      p: "Pesquise MSI-X (Message Signaled Interrupts): dispositivos PCIe enviam interrupções como mensagens na memória, roteando a núcleos específicos e melhorando desempenho vs interrupções baseadas em pinos.",
      req: ["linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Subsistema de Entrada/Saida</text><rect x="15" y="35" width="85" height="40" rx="5" fill="#4338ca"/><text x="57" y="53" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Polling</text><text x="57" y="69" text-anchor="middle" fill="#e2e8f0" font-size="8">CPU verifica</text><rect x="108" y="35" width="85" height="40" rx="5" fill="#059669"/><text x="150" y="53" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Interrupção</text><text x="150" y="69" text-anchor="middle" fill="#e2e8f0" font-size="8">IRQ</text><rect x="200" y="35" width="85" height="40" rx="5" fill="#f59e0b"/><text x="242" y="53" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">DMA</text><text x="242" y="69" text-anchor="middle" fill="#e2e8f0" font-size="8">Sem CPU</text><rect x="30" y="95" width="240" height="30" rx="6" fill="#1e293b"/><text x="150" y="115" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">NVMe / PCIe DMA - milhoes de IOPS</text><text x="150" y="155" text-anchor="middle" fill="#4338ca" font-size="9">/proc/interrupts</text><text x="150" y="180" text-anchor="middle" fill="#4338ca" font-size="9">MSI-X: interrupções direcionadas por nucleo</text></svg>' },
    { icon: "💿", t: "Escalonamento de disco",
      c: "O braço do disco rígido (HDD) se move como o braço de uma pick-up em um disco de vinil: busca a trilha certa (seek time, dominante em HDDs) e espera o setor girar até a posição correta (latência rotacional). Algoritmos: FCFS (ordem de chegada, maior deslocamento), SSTF (menor seek primeiro, mas causa inanição), SCAN (elevador, varre de ponta a ponta), C-SCAN (só uma direção), LOOK e C-LOOK (só até a última requisição). A ordem de atendimento impacta o desempenho.",
      a: "Calcule ordem e deslocamento total para SSTF e SCAN com requisições: 98,183,37,122,14,124,65,67 (início em 53, direção crescente para SCAN). Deslocamento esperado: SSTF ~250, SCAN ~330.",
      p: "Pesquise Deadline Scheduler (leituras com prioridade, tempo de expiração) e CFQ (fatias de tempo justas entre processos) do Linux para escalonamento de E/S.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Escalonamento de Disco</text><rect x="20" y="35" width="60" height="30" rx="4" fill="#4338ca"/><text x="50" y="55" text-anchor="middle" fill="#fff" font-size="9">FCFS</text><rect x="90" y="35" width="60" height="30" rx="4" fill="#059669"/><text x="120" y="55" text-anchor="middle" fill="#fff" font-size="9">SSTF</text><rect x="160" y="35" width="60" height="30" rx="4" fill="#f59e0b"/><text x="190" y="55" text-anchor="middle" fill="#fff" font-size="9">SCAN</text><rect x="230" y="35" width="60" height="30" rx="4" fill="#2563eb"/><text x="260" y="55" text-anchor="middle" fill="#fff" font-size="9">C-SCAN</text><rect x="30" y="85" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="107" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Elevador: varre ate o extremo</text><rect x="50" y="135" width="200" height="30" rx="5" fill="#4338ca"/><text x="150" y="155" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Deadline / CFQ (Linux)</text></svg>' },
    { icon: "🗃️", t: "Subsistemas de E/S",
      c: "Buffering é uma área temporária para compensar diferenças de velocidade, como uma caixa d'água que regula o fluxo. Caching é uma cópia de dados recentes em memória rápida, como manter os documentos mais usados em cima da mesa. Spooling é uma fila de saída para dispositivos compartilhados, como a fila da impressora. Device drivers são tradutores: convertem comandos genéricos (read/write) para comandos específicos do hardware. No Linux: character (fluxo de bytes), block (blocos) e network (pacotes).",
      a: "Crie programa Python que simule spooling de impressão com fila de prioridades (heapq). Documentos têm nome, prioridade e páginas. Spooler processa por prioridade e ordem de chegada. Ver ordem correta de processamento.",
      p: "Pesquise o VFS (Virtual File System) do Linux: como abstrai FS diferentes (ext4, ntfs, tmpfs, procfs) via inode, dentry, super_block e file_operations, permitindo mesmas syscalls independente do tipo.",
      req: ["python3"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Subsistemas de E/S</text><rect x="20" y="35" width="80" height="35" rx="5" fill="#4338ca"/><text x="60" y="57" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Buffering</text><rect x="110" y="35" width="80" height="35" rx="5" fill="#059669"/><text x="150" y="57" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Caching</text><rect x="200" y="35" width="80" height="35" rx="5" fill="#f59e0b"/><text x="240" y="57" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Spooling</text><rect x="30" y="85" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="107" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Device Drivers: char / block / net</text><rect x="30" y="135" width="240" height="30" rx="6" fill="#4338ca"/><text x="150" y="155" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">VFS: inode / dentry / super_block</text></svg>' },
    { icon: "🛡️", t: "Proteção",
      c: "Proteção controla quem pode acessar o quê no sistema. Domínios de proteção são conjuntos de permissões por usuário/grupo, como crachás de funcionários. Matriz de acesso: linhas = funcionários (domínios), colunas = salas (recursos). ACLs são listas de permissões por recurso (quem pode entrar na sala), usado no Windows NTFS e Linux NFSv4. Capabilities são listas de permissões por processo (o que cada programa pode fazer), sem precisar de root total. Linux moderno usa ACLs para arquivos e capabilities para processos.",
      a: "Analise permissões com ls -la. Altere com chmod 755 (rwxr-xr-x) e chmod 644 (rw-r--r--). Explique cada campo: tipo, permissões, link count, dono, grupo, tamanho, data. Domine notação octal e simbólica.",
      p: "Pesquise SELinux: modos Enforcing (aplica política), Permissive (apenas log), Disabled. Políticas: targeted (serviços específicos) e strict (todo sistema). Comandos sestatus, getenforce, audit2allow.",
      req: ["linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Proteção</text><rect x="15" y="35" width="85" height="40" rx="5" fill="#4338ca"/><text x="57" y="53" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">ACLs</text><text x="57" y="69" text-anchor="middle" fill="#e2e8f0" font-size="8">por recurso</text><rect x="108" y="35" width="85" height="40" rx="5" fill="#059669"/><text x="150" y="53" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Capabilities</text><text x="150" y="69" text-anchor="middle" fill="#e2e8f0" font-size="8">por processo</text><rect x="200" y="35" width="85" height="40" rx="5" fill="#f59e0b"/><text x="242" y="53" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Matriz</text><text x="242" y="69" text-anchor="middle" fill="#e2e8f0" font-size="8">de Acesso</text><rect x="30" y="95" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="117" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">rwx (dono/grupo/outros)</text><text x="150" y="155" text-anchor="middle" fill="#4338ca" font-size="9">SELinux: Enforcing / Permissive / Disabled</text><text x="150" y="180" text-anchor="middle" fill="#4338ca" font-size="9">chmod / chown / chage</text></svg>' },
    { icon: "🔐", t: "Segurança em SO",
      c: "Ameaças: malware (programas maliciosos), exploits (ataques a vulnerabilidades), engenharia social (golpes psicológicos como phishing). Autenticação é a prova de quem você é: algo que sabe (senha), algo que tem (token RSA/YubiKey) ou algo que é (biometria, como digital). Autorização define o que você pode fazer depois de autenticado. Criptografia: AES-256 (segredo compartilhado, como um cofre) para dados em repouso, RSA-4096 (chave pública/privada, como um cadeado com duas chaves) para comunicação.",
      a: "Identifique 3 medidas de segurança do seu SO (firewall, criptografia de disco, UAC, sandboxing, autenticação biométrica). Explique ameaças mitigadas por cada uma. Relatório com medidas, ameaças e nível de proteção.",
      p: "Pesquise o Sandbox do macOS: app sandboxing restringe acesso a arquivos/rede/hardware/IPC via entitlements. Compare com permissões do Android (grupos revogáveis em Settings > Apps).",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "🦠", t: "Malware e defesas",
      c: "Malware é como um invasor na sua casa digital: vírus (gruda em programas legítimos), worm (se espalha sozinho pela rede, ex: Morris 1988), trojan (se disfarça de programa útil, ex: Emotet), ransomware (sequestra seus arquivos, ex: WannaCry 2017), rootkit (se esconde no sistema, alterando o kernel). Defesas: antivírus (procura por assinaturas conhecidas e comportamento suspeito), firewall (filtra o que entra e sai), UEFI Secure Boot, detecção de anomalias e assinatura de código.",
      a: "Crie resumo dos principais ransomwares: WannaCry (EternalBlue, 230k máquinas), Petya/NotPetya (boot, Ucrânia), LockBit (RaaS). Inclua vetor, impacto e prevenção (backup 3-2-1, patches, segmentação de rede).",
      p: "Pesquise rootkits modernos: DKOM (oculta processos/arquivos), hooking de syscalls (sys_call_table), detecção via integridade de memória e assinatura digital de módulos do kernel (kmodsign).",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Malware</text><rect x="15" y="35" width="55" height="35" rx="4" fill="#dc2626"/><text x="42" y="53" text-anchor="middle" fill="#fff" font-size="9">Virus</text><text x="42" y="67" text-anchor="middle" fill="#e2e8f0" font-size="7">Executavel</text><rect x="80" y="35" width="55" height="35" rx="4" fill="#dc2626"/><text x="107" y="53" text-anchor="middle" fill="#fff" font-size="9">Worm</text><text x="107" y="67" text-anchor="middle" fill="#e2e8f0" font-size="7">Rede</text><rect x="145" y="35" width="55" height="35" rx="4" fill="#dc2626"/><text x="172" y="53" text-anchor="middle" fill="#fff" font-size="9">Trojan</text><text x="172" y="67" text-anchor="middle" fill="#e2e8f0" font-size="7">Disfarcado</text><rect x="210" y="35" width="55" height="35" rx="4" fill="#dc2626"/><text x="237" y="53" text-anchor="middle" fill="#fff" font-size="9">Ransom</text><text x="237" y="67" text-anchor="middle" fill="#e2e8f0" font-size="7">Sequestro</text><rect x="30" y="85" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="107" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Rootkit: DKOM / hook syscalls</text><rect x="30" y="130" width="240" height="30" rx="6" fill="#4338ca"/><text x="150" y="150" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Backup 3-2-1 / Patches / Firewall</text></svg>' },
    { icon: "🐧", t: "Arquitetura do Linux",
      c: "Kernel Linux é como um canivete suíço: monolítico (tudo integrado) mas com módulos carregáveis (LKM) que podem ser inseridos/removidos em tempo real. Subsistemas: scheduler CFS (árvore rubro-negra, justo e eficiente), VFS (interface única para qualquer sistema de arquivos), pilha de rede (netfilter, nftables), gerenciador de memória. /proc (procfs): informações do kernel e processos. /sys (sysfs): dispositivos, drivers e barramentos. Kernel escrito em C + assembly. Código aberto (GPL).",
      a: "Explore /proc/cpuinfo (modelo, cache, flags), /proc/meminfo (RAM), /proc/version (kernel, compilador) e /proc/self/maps (mapeamento de memória). Explique o que cada um contém.",
      p: "Pesquise boot do Linux: BIOS/UEFI → GRUB2 → kernel (vmlinuz) → initramfs → pivot_root → systemd → targets → serviços. Descreva cada etapa.",
      req: ["linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Arquitetura Linux</text><rect x="20" y="35" width="260" height="25" rx="4" fill="#4338ca"/><text x="150" y="52" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Kernel Monolítico com Modulos (LKM)</text><rect x="20" y="68" width="80" height="30" rx="4" fill="#059669"/><text x="60" y="88" text-anchor="middle" fill="#fff" font-size="9">Scheduler</text><rect x="110" y="68" width="80" height="30" rx="4" fill="#059669"/><text x="150" y="88" text-anchor="middle" fill="#fff" font-size="9">VFS</text><rect x="200" y="68" width="80" height="30" rx="4" fill="#059669"/><text x="240" y="88" text-anchor="middle" fill="#fff" font-size="9">Network</text><rect x="20" y="106" width="80" height="30" rx="4" fill="#f59e0b"/><text x="60" y="126" text-anchor="middle" fill="#fff" font-size="9">Memory</text><rect x="110" y="106" width="80" height="30" rx="4" fill="#f59e0b"/><text x="150" y="126" text-anchor="middle" fill="#fff" font-size="9">Device</text><rect x="200" y="106" width="80" height="30" rx="4" fill="#f59e0b"/><text x="240" y="126" text-anchor="middle" fill="#fff" font-size="9">procfs</text><rect x="50" y="150" width="200" height="25" rx="5" fill="#1e293b"/><text x="150" y="167" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">GRUB2 → kernel → systemd</text></svg>' },
    { icon: "💻", t: "Gerenciamento no Linux",
      c: "Comandos essenciais: ps aux (lista processos), top/htop (monitora em tempo real), kill (envia sinais: SIGTERM=15 pede para fechar, SIGKILL=9 mata forçado), nice/renice (ajusta prioridade de -20 a 19), free -h (RAM+swap), df -h (espaço em disco), du -sh (tamanho de pasta). systemd: systemctl start/stop/status serviço. journalctl: logs do systemd. /etc: configurações do sistema (passwd, fstab, ssh, nginx).",
      a: "Use top para maior consumo de CPU. systemctl list-units --type=service para serviços rodando. Identifique 3 serviços essenciais e explique sua função.",
      p: "Pesquise systemd: por que substituiu SysVinit (paralelismo, unit files, socket activation, journald, systemd-analyze blame).",
      req: ["linux","systemd"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Gerenciamento Linux</text><rect x="20" y="35" width="80" height="30" rx="4" fill="#4338ca"/><text x="60" y="55" text-anchor="middle" fill="#fff" font-size="9">ps aux</text><rect x="110" y="35" width="80" height="30" rx="4" fill="#059669"/><text x="150" y="55" text-anchor="middle" fill="#fff" font-size="9">top/htop</text><rect x="200" y="35" width="80" height="30" rx="4" fill="#f59e0b"/><text x="240" y="55" text-anchor="middle" fill="#fff" font-size="9">kill</text><rect x="20" y="75" width="80" height="30" rx="4" fill="#059669"/><text x="60" y="95" text-anchor="middle" fill="#fff" font-size="9">systemctl</text><rect x="110" y="75" width="80" height="30" rx="4" fill="#059669"/><text x="150" y="95" text-anchor="middle" fill="#fff" font-size="9">journalctl</text><rect x="200" y="75" width="80" height="30" rx="4" fill="#059669"/><text x="240" y="95" text-anchor="middle" fill="#fff" font-size="9">free / df</text><rect x="30" y="125" width="240" height="30" rx="6" fill="#1e293b"/><text x="150" y="145" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">nice / renice (prioridade -20 a 19)</text><text x="150" y="182" text-anchor="middle" fill="#4338ca" font-size="9">systemd-analyze blame</text></svg>' },
    { icon: "📜", t: "Prática: comandos e scripts",
      c: "Shell script é como uma receita de bolo para o Linux: uma sequência de comandos automatizados. Shebang (#!/bin/bash) indica o interpretador. Variáveis guardam valores, condicionais (if/elif/else) tomam decisões, loops (for/while) repetem tarefas, funções organizam o código. Redirecionamento: > (saída para arquivo), < (entrada de arquivo), | (liga comandos em tubo), 2> (erros). chmod +x torna executável. grep filtra texto com regex, sed substitui, awk processa colunas.",
      a: "Crie script bash que receba diretório como argumento e liste arquivos >1MB ordenados por tamanho (maior primeiro). Use find, du -b, sort -rn. Ex: ./maiores.sh /var/log.",
      p: "Pesquise expressões regulares: grep -E (+, ?, {n,m}, |), sed (substituição, deleção), awk (processamento de colunas com arrays associativos).",
      req: ["linux","bash"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Shell Script</text><rect x="50" y="35" width="200" height="30" rx="5" fill="#4338ca"/><text x="150" y="55" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">#!/bin/bash</text><rect x="20" y="75" width="80" height="30" rx="4" fill="#059669"/><text x="60" y="95" text-anchor="middle" fill="#fff" font-size="9">grep -E</text><rect x="110" y="75" width="80" height="30" rx="4" fill="#059669"/><text x="150" y="95" text-anchor="middle" fill="#fff" font-size="9">sed</text><rect x="200" y="75" width="80" height="30" rx="4" fill="#059669"/><text x="240" y="95" text-anchor="middle" fill="#fff" font-size="9">awk</text><rect x="30" y="120" width="240" height="30" rx="6" fill="#f59e0b"/><text x="150" y="140" text-anchor="middle" fill="#fff" font-size="9">Redirecionamento: > | 2> &>></text><rect x="30" y="158" width="240" height="25" rx="5" fill="#1e293b"/><text x="150" y="175" text-anchor="middle" fill="#fff" font-size="9">chmod +x / variaveis / loops / funções</text></svg>' },
    { icon: "🪟", t: "Arquitetura do Windows",
      c: "Windows NT kernel é híbrido: partes monolíticas (serviços no mesmo espaço para desempenho) + microkernel (subsistemas isolados). HAL abstrai o hardware, permitindo rodar em x86, x64 e ARM. Subsistemas: Win32 (aplicações tradicionais), POSIX (legado), WSL (Linux). Win32 API inclui CreateProcess, CreateFile, GDI para gráficos. Drivers: WDDM (GPU) e WDF (KMDF para kernel-mode, UMDF para user-mode).",
      a: "Abra Gerenciador de Tarefas (Ctrl+Shift+Esc): Processos, Desempenho, Histórico, Inicialização. Identifique processo com maior CPU e maior memória.",
      p: "Pesquise diferenças NT kernel vs Linux: prioridades (32 níveis vs CFS), memória (working set vs LRU), drivers (WDF vs V4L2/DRM), licenciamento.",
      req: ["windows"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Arquitetura Windows NT</text><rect x="50" y="35" width="200" height="30" rx="5" fill="#4338ca"/><text x="150" y="55" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Kernel Híbrido NT</text><rect x="20" y="75" width="130" height="30" rx="5" fill="#059669"/><text x="85" y="95" text-anchor="middle" fill="#fff" font-size="9">HAL (Hardware Abstraction)</text><rect x="160" y="75" width="120" height="30" rx="5" fill="#059669"/><text x="220" y="95" text-anchor="middle" fill="#fff" font-size="9">Win32 API</text><rect x="20" y="115" width="130" height="30" rx="5" fill="#f59e0b"/><text x="85" y="135" text-anchor="middle" fill="#fff" font-size="9">WDDM (GPU)</text><rect x="160" y="115" width="120" height="30" rx="5" fill="#f59e0b"/><text x="220" y="135" text-anchor="middle" fill="#fff" font-size="9">WDF (drivers)</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="9">WSL: Windows Subsystem for Linux</text></svg>' },
    { icon: "⚡", t: "Gerenciamento no Windows",
      c: "Ferramentas: Gerenciador de Tarefas (taskmgr, Ctrl+Shift+Esc), Performance Monitor (perfmon, contadores de desempenho), PowerShell (cmdlets como Get-Process e Get-Service, shell orientado a objetos .NET), Gerenciador de Dispositivos (devmgmt.msc), Gerenciamento de Disco (diskmgmt.msc), Visualizador de Eventos (eventvwr.msc), Serviços (services.msc).",
      a: "PowerShell: Get-Process | Sort-Object CPU -Descending | Select -First 10 para top 10 CPU. Export-Csv para CSV. Arquivo CSV com processos ordenados por CPU.",
      p: "Pesquise Process Explorer (Sysinternals) vs Task Manager: handles, DLLs, árvore de processos, assinatura digital, GPU (versões recentes).",
      req: ["windows","powershell"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "⚖️", t: "Comparativo Linux vs Windows",
      c: "Linux: kernel monolítico com módulos, sistema de arquivos ext4, gerenciador de pacotes apt/dnf, interface CLI+GUI, licença GPL (código aberto). Windows: kernel híbrido, NTFS, instaladores .exe/.msi + winget, GUI+PowerShell, proprietário (pago). Linux domina servidores (96% dos top 1M), computação em nuvem e sistemas embarcados. Windows domina desktops (76%) e empresas (Active Directory, Exchange). Ambos suportam containers (Docker, WSL).",
      a: "Crie tabela comparativa com 10+ critérios: kernel, FS, pacotes, shell, interface, licenciamento, segurança, mercado, drivers, servidores. Descreva abordagem de cada SO por critério.",
      p: "Pesquise WSL: WSL1 (tradução de syscalls) vs WSL2 (VM com kernel real em Hyper-V), desempenho I/O, acesso a /mnt/c, impacto no desenvolvimento multiplataforma.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Linux vs Windows</text><rect x="15" y="35" width="130" height="30" rx="5" fill="#4338ca"/><text x="80" y="55" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Linux: Monolítico</text><rect x="155" y="35" width="130" height="30" rx="5" fill="#2563eb"/><text x="220" y="55" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Windows: Híbrido</text><rect x="15" y="75" width="130" height="30" rx="5" fill="#059669"/><text x="80" y="95" text-anchor="middle" fill="#fff" font-size="9">ext4 / apt / GPL</text><rect x="155" y="75" width="130" height="30" rx="5" fill="#f59e0b"/><text x="220" y="95" text-anchor="middle" fill="#fff" font-size="9">NTFS / Proprietario</text><rect x="30" y="120" width="240" height="30" rx="6" fill="#1e293b"/><text x="150" y="140" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Servidores (96%) vs Desktop (76%)</text><text x="150" y="180" text-anchor="middle" fill="#4338ca" font-size="9">WSL2: VM com kernel Linux real</text></svg>' },
    { icon: "📖", t: "Revisão",
      c: "Revisão dos tópicos da P2. Memória: paginação (TLB, tabela de páginas), segmentação, substituição de páginas (FIFO, LRU, Ótimo), thrashing (sistema sobrecarregado de paginação), working-set (conjunto de páginas que o processo usa). Sistemas de arquivos: inodes, diretórios, montagem, journaling. E/S: hardware (interrupções, DMA), escalonamento de disco (FCFS, SSTF, SCAN, C-SCAN), buffering, caching, spooling. Proteção e segurança: ACLs, capabilities, autenticação, criptografia, malware.",
      a: "Resolva 10 exercícios: (1-3) cálculo de endereços com paginação, (4-5) FIFO/LRU, (6-7) seek SSTF/SCAN, (8) permissões UNIX, (9) turnaround, (10) grafo de deadlock.",
      p: "Identifique tópicos com maior dificuldade e revise capítulos 8-12 do Silberschatz (Operating System Concepts) para memória, FS e E/S.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "📝", t: "Exercícios",
      c: "Sessão prática em grupo para fixação. Tradução de endereços com paginação: endereço lógico → página + offset → tabela de páginas → endereço físico. Cálculo TLB: tempo médio = acertos × velocidade_acerto + erros × velocidade_erro. Page faults com FIFO/LRU/Ótimo. Escalonamento de disco: SSTF, SCAN, C-SCAN. Permissões Unix: conversão entre octal e rwx.",
      a: "Em duplas, resolva: paginação de 4KB, página 0x3A, offset 0x7F, tabela [0x8,0x3,0x5,0x1]. Endereço físico? Resposta: frame=0x3, end=0x3×0x1000+0x7F=0x307F.",
      p: "Pesquise impacto do tamanho da TLB: maior TLB reduz miss rate mas aumenta latência de miss. Trade-off entre cobertura (páginas mapeadas) e velocidade de acesso.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "📝", t: "Prova 2",
      c: "Avaliação individual do segundo bimestre. Conteúdo: gerência de memória (paginação, segmentação, TLB, substituição, thrashing), sistemas de arquivos (inodes, diretórios, montagem, journaling), E/S (interrupções, DMA, escalonamento de disco, buffering, caching, spooling), proteção e segurança (ACL, criptografia, malware). Questões discursivas, cálculos e simulações. Duração: 50 minutos. Consulta: material impresso.",
      a: "Leia todas as questões primeiro. Calcule 5 min por questão. Responda primeiro o que sabe bem. Revise antes de entregar.",
      p: "Após correção, revise erros com feedback do professor. Conteúdos da P2 serão cobrados na Prova Final.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "📦", t: "Conceitos de virtualização",
      c: "Virtualização é como um prédio de escritórios onde cada sala funciona como se fosse uma casa completa. Tipo 1 (bare-metal): VMware ESXi, Hyper-V, Xen — rodam direto no hardware, máximo desempenho (datacenters). Tipo 2 (hosted): VirtualBox, VMware Workstation — rodam sobre outro SO (desenvolvimento). Full virtualization: convidado não precisa ser modificado, hypervisor traduz instruções (KVM com VT-x/AMD-V). Paravirtualização: convidado modificado com hypercalls (Xen PV), melhor desempenho. Containers compartilham o kernel do host.",
      a: "Instale VirtualBox (ou KVM/QEMU no Linux). Crie VM Ubuntu Server com 2GB RAM, 20GB disco, rede bridge. Teste conectividade com ping.",
      p: "Pesquise Intel VT-x (VMX root/guest, EPT) e AMD-V (ASID, NPT). Como essas extensões de hardware permitem virtualização eficiente sem interpretação binária.",
      req: ["virtualbox"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Virtualização</text><rect x="60" y="25" width="180" height="25" rx="5" fill="#4338ca"/><text x="150" y="42" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Hypervisor (VMM)</text><rect x="15" y="60" width="130" height="35" rx="5" fill="#059669"/><text x="80" y="80" text-anchor="middle" fill="#fff" font-size="9">VM Tipo 1 (bare-metal)</text><text x="80" y="94" text-anchor="middle" fill="#e2e8f0" font-size="7">VMware ESXi / Hyper-V</text><rect x="155" y="60" width="130" height="35" rx="5" fill="#7c3aed"/><text x="220" y="80" text-anchor="middle" fill="#fff" font-size="9">VM Tipo 2 (hosted)</text><text x="220" y="94" text-anchor="middle" fill="#e2e8f0" font-size="7">VirtualBox / VMware WS</text><rect x="30" y="110" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="132" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Paravirtualização / VT-x / AMD-V</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="9">KVM + QEMU (Linux)</text></svg>' },
    { icon: "🐳", t: "Containers",
      c: "Container é como um apartamento em um prédio: cada um tem seu próprio espaço (aplicação + dependências) mas todos compartilham a mesma infraestrutura (kernel do SO). Namespaces isolam o que cada container vê (PID, rede, montagem, usuário). cgroups limitam recursos (CPU, memória, disco). Docker empacota aplicação + dependências em imagens. Imagem é a planta (template, só leitura), container é o apartamento em si (instância executando). Docker Hub é o mercado de plantas (repositório público de imagens).",
      a: "Instale Docker. Execute: docker run hello-world, docker pull nginx, docker run -d -p 8080:80 nginx. Acesse http://localhost:8080 para ver página do nginx.",
      p: "Pesquise diferença entre containers Docker e VMs tradicionais: isolamento (namespaces vs hypervisor), desempenho (syscall direta vs tradução), tamanho (MB vs GB), boot (segundos vs minutos).",
      req: ["docker"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Containers</text><rect x="50" y="30" width="200" height="30" rx="5" fill="#4338ca"/><text x="150" y="50" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Container Engine (Docker)</text><rect x="15" y="70" width="80" height="40" rx="5" fill="#059669"/><text x="55" y="90" text-anchor="middle" fill="#fff" font-size="9">App A</text><text x="55" y="105" text-anchor="middle" fill="#e2e8f0" font-size="7">lib + bin</text><rect x="110" y="70" width="80" height="40" rx="5" fill="#059669"/><text x="150" y="90" text-anchor="middle" fill="#fff" font-size="9">App B</text><text x="150" y="105" text-anchor="middle" fill="#e2e8f0" font-size="7">lib + bin</text><rect x="205" y="70" width="80" height="40" rx="5" fill="#059669"/><text x="245" y="90" text-anchor="middle" fill="#fff" font-size="9">App C</text><text x="245" y="105" text-anchor="middle" fill="#e2e8f0" font-size="7">lib + bin</text><rect x="30" y="125" width="240" height="25" rx="5" fill="#1e293b"/><text x="150" y="142" text-anchor="middle" fill="#fff" font-size="9">Kernel do SO (compartilhado)</text><text x="150" y="180" text-anchor="middle" fill="#4338ca" font-size="9">cgroups + namespaces (Linux)</text></svg>' },
    { icon: "🐳", t: "Prática com Docker",
      c: "Comandos: docker build (cria imagem a partir de Dockerfile), docker run (executa container), docker ps (lista containers ativos), docker compose (orquestra múltiplos containers). Dockerfile: FROM (imagem base), RUN (comandos de instalação), COPY (arquivos), CMD (comando padrão), EXPOSE (porta). docker-compose.yml define serviços, redes e volumes. Mapeamento de portas (host:container) como ligar uma tomada. Volumes para persistência (dados sobrevivem ao container).",
      a: "Crie Dockerfile para app Node.js simples e docker-compose.yml com app + PostgreSQL. Exponha porta 3000. docker-compose up para subir ambos serviços.",
      p: "Pesquise Kubernetes: conceitos de Pod (menor unidade), Service (exposição), Deployment (escalonamento/rollout). Compare com Docker Compose (single host vs cluster).",
      req: ["docker","docker-compose"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Prática com Docker</text><rect x="20" y="35" width="120" height="30" rx="5" fill="#4338ca"/><text x="80" y="55" text-anchor="middle" fill="#fff" font-size="9">docker build</text><rect x="160" y="35" width="120" height="30" rx="5" fill="#059669"/><text x="220" y="55" text-anchor="middle" fill="#fff" font-size="9">docker run</text><rect x="20" y="75" width="120" height="30" rx="5" fill="#7c3aed"/><text x="80" y="95" text-anchor="middle" fill="#fff" font-size="9">docker-compose</text><rect x="160" y="75" width="120" height="30" rx="5" fill="#f59e0b"/><text x="220" y="95" text-anchor="middle" fill="#fff" font-size="9">Dockerfile</text><rect x="30" y="125" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="147" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">docker ps / images / exec / logs</text><text x="150" y="182" text-anchor="middle" fill="#4338ca" font-size="9">docker-compose.yml: servicos + volumes + redes</text></svg>' },
    { icon: "📱", t: "Android",
      c: "Android é baseado em Linux (kernel modificado). Arquitetura: Linux kernel (base), HAL (abstração de hardware), ART (Android Runtime, compila aplicativos na instalação), Application Framework (Activities para telas, Services para fundo, Content Providers para dados, Broadcast Receivers para eventos). Gerenciamento de memória: Low Memory Killer (LMK) mata processos quando a RAM está baixa. Permissões: revogáveis desde Android 6.0 (o usuário decide na hora). Project Treble (8.0) separa framework do hardware para atualizações mais rápidas.",
      a: "Habilite Modo Desenvolvedor (Sobre > Número da compilação 7x). Ative Depuração USB. Explore: Relatório de Bug, Uso de RAM, Processos em Execução.",
      p: "Pesquise Project Treble (Android 8.0): como separa framework do vendor HAL para acelerar atualizações, VINTF (vendor interface), e particionamento system/vendor.",
      req: ["android"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Android</text><rect x="60" y="30" width="180" height="30" rx="5" fill="#4338ca"/><text x="150" y="50" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Android SO</text><rect x="20" y="70" width="120" height="30" rx="5" fill="#059669"/><text x="80" y="90" text-anchor="middle" fill="#fff" font-size="9">Linux Kernel</text><rect x="160" y="70" width="120" height="30" rx="5" fill="#7c3aed"/><text x="220" y="90" text-anchor="middle" fill="#fff" font-size="9">ART Runtime</text><rect x="20" y="110" width="120" height="30" rx="5" fill="#f59e0b"/><text x="80" y="130" text-anchor="middle" fill="#fff" font-size="9">Framework Java</text><rect x="160" y="110" width="120" height="30" rx="5" fill="#2563eb"/><text x="220" y="130" text-anchor="middle" fill="#fff" font-size="9">Google Play</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="9">AOSP: Android Open Source Project</text></svg>' },
    { icon: "🍎", t: "iOS",
      c: "iOS usa o kernel XNU (híbrido Mach + BSD). Sandboxing rigoroso: cada aplicativo em sua própria jaula (contêiner de segurança), sem acesso aos arquivos dos outros. Gerenciamento de memória: ARC (Automatic Reference Counting) — contagem automática de referências. Linguagem principal: Swift (moderna, segura, rápida). Arquitetura em camadas: Core OS (base), Core Services (serviços), Media (áudio/vídeo), Cocoa Touch (interface). Fechado: apenas hardware Apple. Secure Enclave: coprocessador para dados biométricos e chaves.",
      a: "Compare permissões iOS (câmera, localização, contatos) com Android. Identifique diferenças de abordagem: iOS pede permissão no primeiro uso, Android tem grupos de permissões.",
      p: "Pesquise Secure Enclave do iOS: coprocessador ARM com memória isolada, protege Face ID, Touch ID e chaves criptográficas. Como se comunica com o aplicativo via serviços separados.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">iOS</text><rect x="60" y="30" width="180" height="30" rx="5" fill="#4338ca"/><text x="150" y="50" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">iOS (XNU Kernel)</text><rect x="20" y="70" width="120" height="30" rx="5" fill="#059669"/><text x="80" y="90" text-anchor="middle" fill="#fff" font-size="9">Cocoa Touch</text><rect x="160" y="70" width="120" height="30" rx="5" fill="#7c3aed"/><text x="220" y="90" text-anchor="middle" fill="#fff" font-size="9">Metal (GPU)</text><rect x="20" y="110" width="120" height="30" rx="5" fill="#f59e0b"/><text x="80" y="130" text-anchor="middle" fill="#fff" font-size="9">Swift / Obj-C</text><rect x="160" y="110" width="120" height="30" rx="5" fill="#2563eb"/><text x="220" y="130" text-anchor="middle" fill="#fff" font-size="9">App Store</text><text x="150" y="175" text-anchor="middle" fill="#4338ca" font-size="9">Sandbox: acesso restrito a arquivos/rede</text></svg>' },
    { icon: "🔧", t: "Sistemas embarcados e IoT",
      c: "Sistemas embarcados são computadores dedicados a tarefas específicas, como Arduino e Raspberry Pi. RTOS (sistemas operacionais de tempo real) garantem resposta em tempo determinístico (FreeRTOS, Zephyr). FreeRTOS é popular para IoT: pequeno (<10KB ROM), suporta tarefas, filas, semáforos e timers. Zephyr (Linux Foundation) suporta Bluetooth/BLE, WiFi e segurança (bootloader seguro, update OTA). O escalonamento é preemptivo baseado em prioridade.",
      a: "Crie projeto Arduino IDE que pisque LED a cada 1s e leia sensor de temperatura (LM35/DHT11) enviando pela serial. Conecte e veja dados no Serial Monitor.",
      p: "Pesquise Zephyr RTOS vs FreeRTOS: recursos (sockets, TLS, Bluetooth), suporte a hardware (ARM, RISC-V, Xtensa), segurança (MCUboot, TF-M), e licenciamento (Apache 2.0 vs MIT modificado).",
      req: ["arduino-ide"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Sistemas Embarcados</text><rect x="15" y="35" width="85" height="40" rx="5" fill="#4338ca"/><text x="57" y="53" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">FreeRTOS</text><text x="57" y="69" text-anchor="middle" fill="#e2e8f0" font-size="8">RTOS</text><rect x="108" y="35" width="85" height="40" rx="5" fill="#059669"/><text x="150" y="53" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">ARM Cortex-M</text><text x="150" y="69" text-anchor="middle" fill="#e2e8f0" font-size="8">Microcontrolador</text><rect x="200" y="35" width="85" height="40" rx="5" fill="#f59e0b"/><text x="242" y="53" text-anchor="middle" fill="#fff" font-size="9" font-weight="bold">Arduino</text><text x="242" y="69" text-anchor="middle" fill="#e2e8f0" font-size="8">Plataforma</text><rect x="30" y="95" width="240" height="35" rx="6" fill="#1e293b"/><text x="150" y="117" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">IoT: sensores + atuadores + rede</text><text x="150" y="165" text-anchor="middle" fill="#4338ca" font-size="9">MQTT / CoAP: protocolos IoT</text></svg>' },
    { icon: "🛠️", t: "Projeto: minishell",
      c: "Implementar um shell simplificado em C. Requisitos: ler comandos (fgets), executar via fork+exec (criar processo filho e substituir o programa), suportar pipes (|) para conectar comandos, redirecionamento (> e <) para arquivos, comandos internos (cd, exit, help). Tratar erros com perror. Processos em background (&) sem esperar (waitpid com WNOHANG). Parsear linha de comando com strtok. Gerenciar variáveis de ambiente (setenv/getenv).",
      a: "Implemente versão básica com comandos externos via fork+execvp e cd interno. Teste com ls, pwd, echo, cd /tmp, pwd. Funcionalidade de shell real.",
      p: "Pesquise código fonte do bash (GNU) ou dash — como implementam parsing (gramática yacc), job control (SIGTSTP, SIGCONT), e gerenciamento de jobs (fg, bg).",
      req: ["gcc","linux"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "🛠️", t: "Projeto: simulador de escalonamento",
      c: "Implementar um simulador com interface CLI ou GUI. Deve ler processos (nome, chegada, burst, prioridade) e executar FCFS, SJF, RR (quantum ajustável) e Prioridade. Gerar gráfico de Gantt (textual ou com biblioteca gráfica). Calcular turnaround, espera, throughput e utilização da CPU. Entrada via linha de comando (P1 0 6 2) ou arquivo. Saída em tabela e Gantt para comparação entre algoritmos.",
      a: "Implemente CLI que aceite entrada como P1 0 6 2 (nome, chegada, burst, prioridade). Gere saída tabular com métricas para cada algoritmo. Gantt textual.",
      p: "Pesquise Scheduling Simulator do livro Operating System Concepts (Silberschatz) como referência de implementação — estruturas de dados e cálculo de métricas.",
      req: ["gcc","python3"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "🛠️", t: "Projeto: alocador de memória",
      c: "Implementar um alocador de memória estilo malloc/free usando sbrk() ou mmap(). Suportar first-fit, best-fit e worst-fit. Manter lista de blocos livres (free list encadeada). Coalescência: juntar blocos livres adjacentes ao liberar, como juntar duas mesas vagas lado a lado. Splitting: dividir bloco grande em menores na alocação, como cortar uma tábua no tamanho certo. Usar cabeçalho (header) em cada bloco com tamanho e flag de livre.",
      a: "Implemente my_malloc(size) com first-fit e my_free(ptr) com coalescência de adjacentes. Teste: alocar 5 blocos, liberar 2 do meio, verificar coalescência.",
      p: "Pesquise ptmalloc (glibc), jemalloc (FreeBSD/Firefox) e tcmalloc (Google): compare fragmentação, desempenho em multithread (arenas) e uso de cache.",
      req: ["gcc","linux","valgrind"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Projeto: Alocador de Memória</text><rect x="30" y="35" width="240" height="35" rx="6" fill="#4338ca"/><text x="150" y="57" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">malloc / free personalizado</text><rect x="30" y="80" width="110" height="35" rx="5" fill="#059669"/><text x="85" y="102" text-anchor="middle" fill="#fff" font-size="9">First-fit</text><rect x="160" y="80" width="110" height="35" rx="5" fill="#f59e0b"/><text x="215" y="102" text-anchor="middle" fill="#fff" font-size="9">Best-fit</text><rect x="50" y="130" width="200" height="30" rx="6" fill="#1e293b"/><text x="150" y="150" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Gerenciamento de memória</text><text x="150" y="185" text-anchor="middle" fill="#4338ca" font-size="9">sbrk / mmap / buddy system</text></svg>' },
    { icon: "👥", t: "Acompanhamento de projetos",
      c: "Sessão de orientação e dúvidas sobre os projetos finais. Revisão de código entre pares (peer review), como dois engenheiros revisando a planta um do outro. Discussão de boas práticas: naming conventions (snake_case em C, PascalCase em Java), modularização (separar em arquivos .h e .c), tratamento de erros (verificar retorno de todas as syscalls), documentação (comentários em Doxygen). Orientação individualizada para cada equipe.",
      a: "Apresente seu progresso para outro grupo e receba feedback. Identifique pontos de melhoria no código, arquitetura e testes. Documente o feedback recebido.",
      p: "Pesquise design patterns para sistemas: padrões de alocação de memória (pool, slab), padrões de concorrência (active object, reactor), e padrões de kernel (device driver, file system).",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Acompanhamento de Projetos</text><rect x="30" y="40" width="240" height="35" rx="6" fill="#4338ca"/><text x="150" y="62" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Revisão de Código (Code Review)</text><rect x="30" y="85" width="110" height="35" rx="5" fill="#059669"/><text x="85" y="107" text-anchor="middle" fill="#fff" font-size="9">Duvidas técnicas</text><rect x="160" y="85" width="110" height="35" rx="5" fill="#f59e0b"/><text x="215" y="107" text-anchor="middle" fill="#fff" font-size="9">Cronograma</text><rect x="30" y="135" width="240" height="30" rx="6" fill="#1e293b"/><text x="150" y="155" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Git: branches / pull requests</text></svg>' },
    { icon: "🧪", t: "Testes e apresentações",
      c: "Testes dos projetos: casos de teste para cada funcionalidade (testes unitários com assert), testes de borda (limites: buffers cheios, strings vazias, arquivos enormes), testes de estresse (múltiplas operações simultâneas, alocações massivas). Apresentação parcial de 5 minutos por grupo: arquitetura geral, implementação atual, demonstração ao vivo, principais desafios. Feedback do professor e colegas para correção de rumo.",
      a: "Prepare apresentação de 5 minutos com: arquitetura do projeto (diagrama), principais desafios técnicos, demonstração ao vivo e lições aprendidas até o momento.",
      p: "Pesquise técnicas de debugging em C: gdb (breakpoints, backtrace, watch), Valgrind (memcheck para vazamentos, helgrind para race conditions), AddressSanitizer (ASan) para detecção de buffer overflow.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Testes e Apresentações</text><rect x="20" y="40" width="120" height="35" rx="5" fill="#4338ca"/><text x="80" y="60" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Testes Unitários</text><rect x="160" y="40" width="120" height="35" rx="5" fill="#059669"/><text x="220" y="60" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Testes de Stress</text><rect x="30" y="90" width="240" height="35" rx="6" fill="#f59e0b"/><text x="150" y="112" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Apresentação: 10 min + perguntas</text><rect x="50" y="140" width="200" height="30" rx="6" fill="#1e293b"/><text x="150" y="160" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">Valgrind / gdb para debug</text></svg>' },
    { icon: "✅", t: "Entrega dos projetos",
      c: "Entrega final completa: código fonte no GitHub, relatório técnico (arquitetura, decisões de projeto, resultados, screenshots), README com instruções de compilação (make/gcc) e uso. Apresentação final de 10 minutos com demonstração completa e discussão dos resultados. Prazo final improrrogável. Avaliação: 40% código (organização e funcionamento), 30% relatório, 30% apresentação.",
      a: "Finalize repositório GitHub: README com descrição, instruções de build (make/gcc), exemplos de uso. Submeta o link. Verificar se o código compila sem warnings.",
      p: "Pesquise boas práticas de README: badges de build, exemplos de código, instruções claras de instalação/uso, licença, contribuição. Exemplos de README de projetos open source populares.",
      req: ["git"],
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><text x="150" y="22" text-anchor="middle" fill="#4338ca" font-size="12" font-weight="bold">Entrega dos Projetos</text><rect x="30" y="40" width="240" height="35" rx="6" fill="#4338ca"/><text x="150" y="62" text-anchor="middle" fill="#fff" font-size="11" font-weight="bold">Entrega via GitHub</text><rect x="30" y="85" width="110" height="40" rx="5" fill="#059669"/><text x="85" y="105" text-anchor="middle" fill="#fff" font-size="9">Relatorio Técnico</text><rect x="160" y="85" width="110" height="40" rx="5" fill="#f59e0b"/><text x="215" y="105" text-anchor="middle" fill="#fff" font-size="9">Código Fonte</text><rect x="50" y="140" width="200" height="30" rx="6" fill="#1e293b"/><text x="150" y="160" text-anchor="middle" fill="#fff" font-size="10" font-weight="bold">README + Makefile + testes</text></svg>' },
    { icon: "📖", t: "Revisão: processos e threads",
      c: "Revisão integrada para prova final. Processos: estados (novo, pronto, execução, bloqueado, terminado), PCB (bloco de controle), troca de contexto, escalonamento (FCFS, SJF, RR, Prioridade, Multinível). Threads: modelos (N:1, 1:1, N:M), pthreads. Sincronização: seção crítica, semáforos (wait/signal, mutex), monitores, problemas clássicos (produtor-consumidor, leitores-escritores, jantar dos filósofos). Deadlocks: condições de Coffman, grafo de alocação, algoritmo do Banqueiro.",
      a: "Resolva exercícios integrados: calcular turnaround com RR + verificar deadlock em grafo + implementar sincronização com semáforos em pseudocódigo.",
      p: "Reveja capítulos 3-7 do Silberschatz (Operating System Concepts) como preparação para prova final. Foco em exercícios de fixação no final de cada capítulo.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "📖", t: "Revisão: memória e arquivos",
      c: "Revisão de gerência de memória: paginação (tabela de páginas, TLB, tempo de acesso efetivo), segmentação (base + limite), alocação de quadros (FIFO, LRU, Ótimo, anomalia de Belady), thrashing e working-set (conjunto de páginas em uso). Sistemas de arquivos: inodes (ponteiros diretos/indiretos/duplos), diretórios (arquivos especiais), montagem (mount/umount), superblock, journaling. E/S: escalonamento de disco (SSTF, SCAN, C-SCAN, LOOK), DMA, interrupções, buffering.",
      a: "Resolva 5 exercícios de tradução de endereços com paginação e 5 de algoritmos de substituição de páginas. Calcule tempo de seek com SSTF e SCAN.",
      p: "Reveja capítulos 8-12 do Silberschatz para consolidar conhecimento de memória, sistemas de arquivos e E/S antes da prova final.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "📖", t: "Revisão: virtualização e SO modernos",
      c: "Revisão de virtualização: hypervisors Tipo 1 (bare-metal, como VMware ESXi) e Tipo 2 (hosted, como VirtualBox), full virtualization vs paravirtualização, Intel VT-x e AMD-V. Containers: namespaces (isolamento), cgroups (limites de recursos), Docker, Kubernetes. Linux e Windows: arquiteturas (monolítico vs híbrido), comandos de gerenciamento (systemd vs services.msc). SOs móveis: Android (ART, permissões) e iOS (XNU, sandbox, Secure Enclave). Embarcados: FreeRTOS, Zephyr.",
      a: "Crie mapa mental conectando todos os tópicos da disciplina: processos ↔ sincronização ↔ deadlocks ↔ memória ↔ arquivos ↔ E/S ↔ virtualização ↔ SOs modernos. Identifique relações entre eles.",
      p: "Pesquise tendências atuais em SO: WebAssembly System Interface (WASI), sistemas unikernel (MirageOS, IncludeOS), e SO para computação quântica (Qiskit, Q#).",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "📝", t: "Exercícios de preparação",
      c: "Última revisão antes da prova final. Resolução de exercícios abrangentes de todo o semestre: processos e threads (estados, escalonamento, sincronização), deadlocks (grafo, banqueiro), memória (paginação, TLB, substituição), arquivos (inodes, diretórios, alocação), E/S (DMA, escalonamento de disco), virtualização (hypervisors, containers), Linux e Windows (comandos, arquitetura). Esclarecimento de dúvidas finais e dicas de estratégia de prova.",
      a: "Resolva prova simulada com 10 questões cobrindo todos os tópicos do semestre em 50 minutos (simulando condições reais de prova).",
      p: "Identifique os últimos pontos fracos e faça revisão focada nessas áreas usando o material de aula, livro do Silberschatz e exercícios resolvidos.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "📝", t: "Prova Final",
      c: "Avaliação final individual de todo o conteúdo do semestre. Questões discursivas: explique conceitos como diferença entre paginação e segmentação, como o CFS funciona. Cálculos: turnaround, page faults, seek time, endereços físicos. Análise de cenários: dado um grafo de alocação, há deadlock? Dado código concorrente, há race condition? Valor: 10 pontos. Duração: 100 minutos (2 aulas). Consulta: proibida (exceto se combinado). Proibido uso de dispositivos eletrônicos.",
      a: "Leia todas as questões antes de começar. Gerencie o tempo: 10 min por questão. Comece pelas que domina. Revise antes de entregar. Escreva respostas claras e organizadas.",
      p: "Após a prova, faça autoavaliação do aprendizado no semestre: o que aprendeu, quais áreas precisa desenvolver mais, como os conceitos de SO se conectam com outras disciplinas.",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' },
    { icon: "🎓", t: "Encerramento e resultados",
      c: "Vista de prova com correção comentada e esclarecimento de dúvidas. Divulgação das notas finais e médias. Fechamento da disciplina: feedback dos alunos sobre o curso (metodologia, conteúdo, avaliações) e sugestões para próximos semestres. Considerações finais sobre como os conceitos de SO se aplicam em disciplinas futuras (redes, compiladores, sistemas distribuídos, segurança). Orientação para carreira: SO é base para computação em nuvem, DevOps e sistemas embarcados.",
      a: "Participe da avaliação da disciplina com feedback construtivo: o que funcionou bem, o que pode melhorar, sugestões de tópicos adicionais para próximas turmas.",
      p: "Reflita sobre como os conceitos de SO se aplicam nas outras áreas: sistemas distribuídos (escalonamento, sincronização), segurança (proteção, ACL), computação em nuvem (virtualização, containers), IoT (sistemas embarcados, RTOS).",
      svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200"><rect width="300" height="200" fill="#e2e8f0" rx="8"/><rect x="50" y="40" width="200" height="120" fill="#4338ca" rx="6"/><text x="150" y="108" text-anchor="middle" fill="#fff" font-size="16" font-weight="bold">SO</text></svg>' }
  ]
};